/**
 * Check if a given object implements the PressRelease interface.
 */
export function instanceOfPressRelease(value) {
    if (!("id" in value) || value["id"] === undefined)
        return false;
    if (!("datetime" in value) || value["datetime"] === undefined)
        return false;
    if (!("title" in value) || value["title"] === undefined)
        return false;
    if (!("body" in value) || value["body"] === undefined)
        return false;
    return true;
}
export function PressReleaseFromJSON(json) {
    return PressReleaseFromJSONTyped(json, false);
}
export function PressReleaseFromJSONTyped(json, ignoreDiscriminator) {
    if (json == null) {
        return json;
    }
    return {
        id: json["id"],
        datetime: json["datetime"],
        title: json["title"],
        body: json["body"],
        style: json["style"] == null ? undefined : json["style"],
        language: json["language"] == null ? undefined : json["language"],
    };
}
export function PressReleaseToJSON(json) {
    return PressReleaseToJSONTyped(json, false);
}
export function PressReleaseToJSONTyped(value, ignoreDiscriminator = false) {
    if (value == null) {
        return value;
    }
    return {
        id: value["id"],
        datetime: value["datetime"],
        title: value["title"],
        body: value["body"],
        style: value["style"],
        language: value["language"],
    };
}
